import{_ as s,a,c as t,ac as o}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"第四册：流利英语 · 综合复习与自测 · 第34–44课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","frontmatter":{"title":"第四册：流利英语 · 综合复习与自测 · 第34–44课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","splitFrom":"life/english/new-concept/book-4/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第四册：流利英语 · 综合复习与自测","summary":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · 综合复习与自测 · 第23–33课","link":"/life/english/new-concept/book-4/review-part-03"},"next":{"text":"第四册：流利英语 · 综合复习与自测 · 第45–48课","link":"/life/english/new-concept/book-4/review-part-05"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · 综合复习与自测 · 第23–33课","link":"/life/english/new-concept/book-4/review-part-03"},"next":{"text":"第四册：流利英语 · 综合复习与自测 · 第45–48课","link":"/life/english/new-concept/book-4/review-part-05"}},"headers":[],"relativePath":"life/english/new-concept/book-4/review-part-04.md","filePath":"life/english/new-concept/book-4/review-part-04.md"}'),r={name:"life/english/new-concept/book-4/review-part-04.md"};function n(i,e,l,h,c,p){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="第四册-流利英语-·-综合复习与自测-·-第34–44课" tabindex="-1">第四册：流利英语 · 综合复习与自测 · 第34–44课 <a class="header-anchor" href="#第四册-流利英语-·-综合复习与自测-·-第34–44课" aria-label="Permalink to &quot;第四册：流利英语 · 综合复习与自测 · 第34–44课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-4/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-4/overview">本册介绍</a> · <a href="/life/english/new-concept/book-4/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-4/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-4/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-4/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-4/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-4/review">综合复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-34-·-倾向表达与概率范围" tabindex="-1">Lesson 34 · 倾向表达与概率范围 <a class="header-anchor" href="#lesson-34-·-倾向表达与概率范围" aria-label="Permalink to &quot;Lesson 34 · 倾向表达与概率范围 {#lesson-34-·-倾向表达与概率范围}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> In this club, new members tend to ask their peers for help before approaching an adult.</p><h3 id="练习-1-33" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-33" aria-label="Permalink to &quot;练习 1 {#练习-1-33}&quot;">​</a></h3><p>示例的范围是所有青少年还是这个俱乐部的新成员？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 这个俱乐部的新成员。</p><p><strong>解析：</strong> 地点与主语共同限定了范围。</p></details><p><strong>表达迁移：</strong> 写三句关于一个青年活动组的观察，包含范围限制、可能原因和支持方式。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>In our discussion group, quieter members tend to speak after a friend has contributed. They may feel more confident with familiar support. Offering time to prepare could help everyone participate.</p><p>限定具体群体，用 may 区分推测原因，再给出温和可执行的建议。</p></details><p><a href="/life/english/new-concept/book-4/unit-05/lesson-034">回看本课</a></p><h2 id="lesson-35-·-将来完成时与未来截止点" tabindex="-1">Lesson 35 · 将来完成时与未来截止点 <a class="header-anchor" href="#lesson-35-·-将来完成时与未来截止点" aria-label="Permalink to &quot;Lesson 35 · 将来完成时与未来截止点 {#lesson-35-·-将来完成时与未来截止点}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> By the time the simulated crew arrives, the support team will have checked every system.</p><h3 id="练习-1-34" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-34" aria-label="Permalink to &quot;练习 1 {#练习-1-34}&quot;">​</a></h3><p>示例检查系统是在机组到达之前还是之后完成？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 之前。</p><p><strong>解析：</strong> 将来完成时以到达为截止点。</p></details><p><strong>表达迁移：</strong> 为虚构训练任务写三句进度说明：当前阶段、明日截止点、条件变化。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>We are testing the communication system today. By noon tomorrow, we will have completed the first simulation. If a fault appears, the final rehearsal will be delayed.</p><p>明确模拟情境，把预测截止点与可能改变计划的条件分开。</p></details><p><a href="/life/english/new-concept/book-4/unit-05/lesson-035">回看本课</a></p><h2 id="lesson-36-·-倍数比较与百分比基数" tabindex="-1">Lesson 36 · 倍数比较与百分比基数 <a class="header-anchor" href="#lesson-36-·-倍数比较与百分比基数" aria-label="Permalink to &quot;Lesson 36 · 倍数比较与百分比基数 {#lesson-36-·-倍数比较与百分比基数}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> In the fictional budget, maintenance costs rose from 100 units to 120 units, an increase of 20%.</p><h3 id="练习-1-35" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-35" aria-label="Permalink to &quot;练习 1 {#练习-1-35}&quot;">​</a></h3><p>100增到120，相对增幅是多少？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 20%。</p><p><strong>解析：</strong> (120−100)/100=20%。</p></details><p><strong>表达迁移：</strong> 用三句解释一个虚构预算变化：起止金额、计算增幅、仍需了解的信息。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The repair budget rose from 200 units to 250 units. This is an increase of 25%. We still need to know whether the higher amount covers more work or higher prices.</p><p>数字可直接核算，最后区分数量增长和价格增长，不据金额变化直接判断效率。</p></details><p><a href="/life/english/new-concept/book-4/unit-05/lesson-036">回看本课</a></p><h2 id="lesson-37-·-比较级重复与渐变表达" tabindex="-1">Lesson 37 · 比较级重复与渐变表达 <a class="header-anchor" href="#lesson-37-·-比较级重复与渐变表达" aria-label="Permalink to &quot;Lesson 37 · 比较级重复与渐变表达 {#lesson-37-·-比较级重复与渐变表达}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The records became more and more detailed over the course of the study.</p><h3 id="练习-1-36" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-36" aria-label="Permalink to &quot;练习 1 {#练习-1-36}&quot;">​</a></h3><p>改错：The descriptions became more and more clearer.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The descriptions became clearer and clearer.</p><p><strong>解析：</strong> clearer 已为比较级，不能再加 more。</p></details><p><strong>表达迁移：</strong> 写三句虚构长期研究笔记，谈资料变化和个体差异，不作医疗建议。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Our records became more and more detailed during the five-year project. Participants showed different patterns of change. We should describe that variation rather than rely on one average alone.</p><p>将长期观察与统计概括区分，强调平均值不能替代个体分布。</p></details><p><a href="/life/english/new-concept/book-4/unit-05/lesson-037">回看本课</a></p><h2 id="lesson-38-·-if、when-后的省略结构" tabindex="-1">Lesson 38 · if、when 后的省略结构 <a class="header-anchor" href="#lesson-38-·-if、when-后的省略结构" aria-label="Permalink to &quot;Lesson 38 · if、when 后的省略结构 {#lesson-38-·-if、when-后的省略结构}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> When travelling, check current local guidance rather than rely on an old account.</p><h3 id="练习-1-37" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-37" aria-label="Permalink to &quot;练习 1 {#练习-1-37}&quot;">​</a></h3><p>展开示例中的 When travelling。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> When you are travelling</p><p><strong>解析：</strong> 补回主语 you 与 be。</p></details><p><strong>表达迁移：</strong> 为旅行笔记写三句信息核查提醒：提出未知、寻找当前来源、标记尚未确认事项。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I could not confirm the source described in the old guide. When in doubt, I would check current local information. Any unresolved point should be clearly marked in our notes.</p><p>重点是信息核查而不是自创饮水处置步骤，省略条件句自然嵌入建议。</p></details><p><a href="/life/english/new-concept/book-4/unit-05/lesson-038">回看本课</a></p><h2 id="lesson-39-·-wish-后的时态与非现实意义" tabindex="-1">Lesson 39 · wish 后的时态与非现实意义 <a class="header-anchor" href="#lesson-39-·-wish-后的时态与非现实意义" aria-label="Permalink to &quot;Lesson 39 · wish 后的时态与非现实意义 {#lesson-39-·-wish-后的时态与非现实意义}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> I wish the opening were shorter, because the main point arrives too late.</p><h3 id="练习-1-38" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-38" aria-label="Permalink to &quot;练习 1 {#练习-1-38}&quot;">​</a></h3><p>填空：I wish I ___ checked the references before submitting the draft.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> had</p><p><strong>解析：</strong> 对过去提交前行为的遗憾用 had checked。</p></details><p><strong>表达迁移：</strong> 写三句自我编辑笔记：一个愿望、具体问题和下一步修改。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I wish the argument were easier to follow. The second paragraph introduces three ideas at once. I will separate them and add one concrete example.</p><p>wish 表达不满意，后两句将抽象愿望转为可执行编辑步骤。</p></details><p><a href="/life/english/new-concept/book-4/unit-05/lesson-039">回看本课</a></p><h2 id="lesson-40-·-where-的地点与条件意义" tabindex="-1">Lesson 40 · where 的地点与条件意义 <a class="header-anchor" href="#lesson-40-·-where-的地点与条件意义" aria-label="Permalink to &quot;Lesson 40 · where 的地点与条件意义 {#lesson-40-·-where-的地点与条件意义}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Where the water meets the barrier, the pattern changes.</p><h3 id="练习-1-39" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-39" aria-label="Permalink to &quot;练习 1 {#练习-1-39}&quot;">​</a></h3><p>示例中的 where 主要表示地点还是时间？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 地点。</p><p><strong>解析：</strong> 它指水与障碍物相接的位置。</p></details><p><strong>表达迁移：</strong> 根据下面给出的原创文字情境，改写三句观察：小涟漪在浅盘中向四周扩散；到达盘边时，可见的波纹形态发生变化；这些描述只适用于这个模型。用 where 从句说明变化发生的位置，并在末句保留模型范围的限制，不补写文字中未给出的速度、高度或原因。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Small ripples spread across the tray. Where they meet the edge, the visible pattern changes. This observation describes our model and does not cover every kind of wave.</p><p>第一句改写文字情境中的扩散，第二句用 where 从句指出盘边这一变化位置，第三句保留模型边界。任务只依据本页文字，不要求实际演示或图示，也不把给定情境当作所有水波的普遍规律。</p></details><p><a href="/life/english/new-concept/book-4/unit-05/lesson-040">回看本课</a></p><h2 id="lesson-41-·-with-宾语-补足语" tabindex="-1">Lesson 41 · with + 宾语 + 补足语 <a class="header-anchor" href="#lesson-41-·-with-宾语-补足语" aria-label="Permalink to &quot;Lesson 41 · with + 宾语 + 补足语 {#lesson-41-·-with-宾语-补足语}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> With the observer standing at a distance, the handler recorded the animal’s response.</p><h3 id="练习-1-40" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-40" aria-label="Permalink to &quot;练习 1 {#练习-1-40}&quot;">​</a></h3><p>填空：With the notes ___, the team ended the session.（complete 的过去分词）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> completed</p><p><strong>解析：</strong> notes 是被完成的，使用过去分词。</p></details><p><strong>表达迁移：</strong> 写三句历史动物训练文本的批判性阅读笔记：叙述内容、证据限制、伦理问题。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The account describes an animal responding to a repeated cue. With no independent observations available, the claimed result is difficult to assess. A modern discussion should also consider the animal’s welfare.</p><p>把叙述、可验证性和伦理分开，不提供强制训练操作。</p></details><p><a href="/life/english/new-concept/book-4/unit-06/lesson-041">回看本课</a></p><h2 id="lesson-42-·-被动语态中的时态与体" tabindex="-1">Lesson 42 · 被动语态中的时态与体 <a class="header-anchor" href="#lesson-42-·-被动语态中的时态与体" aria-label="Permalink to &quot;Lesson 42 · 被动语态中的时态与体 {#lesson-42-·-被动语态中的时态与体}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The signal has been recorded, but the data are still being analysed.</p><h3 id="练习-1-41" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-41" aria-label="Permalink to &quot;练习 1 {#练习-1-41}&quot;">​</a></h3><p>填空：The readings are being ___ now.（check）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> checked</p><p><strong>解析：</strong> 现在进行时被动为 are being + 过去分词。</p></details><p><strong>表达迁移：</strong> 写三句虚构仪器报告：已获取内容、正在处理的步骤、尚不能作出的判断。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The signal has been stored successfully. Its timing is still being compared with other records. We cannot yet draw a reliable conclusion about the event from this trace alone.</p><p>被动时态清楚标记处理阶段，末句限定单条记录的解释能力。</p></details><p><a href="/life/english/new-concept/book-4/unit-06/lesson-042">回看本课</a></p><h2 id="lesson-43-·-there-be-与存在命题" tabindex="-1">Lesson 43 · there be 与存在命题 <a class="header-anchor" href="#lesson-43-·-there-be-与存在命题" aria-label="Permalink to &quot;Lesson 43 · there be 与存在命题 {#lesson-43-·-there-be-与存在命题}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> There may be a simpler explanation for the unusual signal.</p><h3 id="练习-1-42" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-42" aria-label="Permalink to &quot;练习 1 {#练习-1-42}&quot;">​</a></h3><p>填空：There ___ two possible explanations in the report.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> are</p><p><strong>解析：</strong> 正式书面语中 be 与后面的复数名词一致。</p></details><p><strong>表达迁移：</strong> 写三句评价虚构异常信号：观察、替代解释、验证需求。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The receiver detected an unusual pattern. There may be an explanation within the instrument itself. Independent observations are needed before we attribute the signal to an external source.</p><p>从观察到解释保留推理间隔，先检验设备来源，避免把异常等同于发现。</p></details><p><a href="/life/english/new-concept/book-4/unit-06/lesson-043">回看本课</a></p><h2 id="lesson-44-·-限制性与非限制性从句的范围差异" tabindex="-1">Lesson 44 · 限制性与非限制性从句的范围差异 <a class="header-anchor" href="#lesson-44-·-限制性与非限制性从句的范围差异" aria-label="Permalink to &quot;Lesson 44 · 限制性与非限制性从句的范围差异 {#lesson-44-·-限制性与非限制性从句的范围差异}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The visitors who had attended the workshop recognised the greeting.</p><h3 id="练习-1-43" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-43" aria-label="Permalink to &quot;练习 1 {#练习-1-43}&quot;">​</a></h3><p>示例是否说所有访客都参加了工作坊？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 没有。</p><p><strong>解析：</strong> 限制性从句只限定其中一组。</p></details><p><strong>表达迁移：</strong> 写三句跨文化活动观察，明确样本并保留社群内部差异。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The participants who had joined earlier sessions recognised the greeting. Others asked about its meaning. Our guide reminded us that practices can vary within the same community.</p><p>用限制性从句划分观察对象，再说明内部多样性，避免绝对文化标签。</p></details><p><a href="/life/english/new-concept/book-4/unit-06/lesson-044">回看本课</a></p>',92)])])}const u=s(r,[["render",n]]);export{m as __pageData,u as default};
